# DFA to accept strings ending with 1

def dfa_ending_with_1(string):

    state = "q0"

    for symbol in string:

        if state == "q0":

            if symbol == "0":
                state = "q0"

            elif symbol == "1":
                state = "q1"

            else:
                return False

        elif state == "q1":

            if symbol == "0":
                state = "q0"

            elif symbol == "1":
                state = "q1"

            else:
                return False

    return state == "q1"


# Taking input from user

string = input("Enter a binary string: ")

if dfa_ending_with_1(string):
    print("String Accepted")
else:
    print("String Rejected")

from collections import deque

# NFA transition table
# Example NFA:
# Accepts binary strings containing at least one '1'

nfa = {
    'q0': {
        '0': {'q0'},
        '1': {'q0', 'q1'}
    },

    'q1': {
        '0': {'q1'},
        '1': {'q1'}
    }
}

alphabet = {'0', '1'}

start_state = frozenset({'q0'})
final_states = {'q1'}


def nfa_to_dfa(nfa, alphabet, start_state, final_states):

    dfa = {}
    queue = deque([start_state])
    visited = set()

    while queue:

        current = queue.popleft()

        if current in visited:
            continue

        visited.add(current)
        dfa[current] = {}

        for symbol in alphabet:

            next_states = set()

            for state in current:

                next_states.update(
                    nfa.get(state, {}).get(symbol, set())
                )

            next_state = frozenset(next_states)

            dfa[current][symbol] = next_state

            if next_state not in visited:
                queue.append(next_state)

    return dfa


dfa = nfa_to_dfa(
    nfa,
    alphabet,
    start_state,
    final_states
)


print("Equivalent DFA")
print("----------------")

for state, transitions in dfa.items():

    print(f"DFA State {set(state)}")

    for symbol, next_state in transitions.items():

        print(
            f"  On {symbol} -> {set(next_state)}"
        )


print("\nDFA Final States")

for state in dfa:

    if state.intersection(final_states):

        print(set(state))
